pub fn present(model: &mut UiModel, state: &State) {
    model.button = slot("#doc/button", &state.button);
    model.icon_button = slot("#doc/icon_button", &state.icon_button);
    model.toggle = slot("#doc/toggle", &state.toggle);
    model.radio_1 = slot("#doc/radio/1", &state.radio.options[0]);
    model.radio_2 = slot("#doc/radio/2", &state.radio.options[1]);
    model.radio_3 = slot("#doc/radio/3", &state.radio.options[2]);
    model.dropdown = slot("#doc/dropdown", &state.dropdown);
    model.list_item = list("#doc/list_item", &state.list_item);
    model.scrollbar = scrollbar("#doc/scrollbar", &state.list_item);
    model.segmented = slot("#doc/segmented", &state.segmented);
    model.tabs = slot("#doc/tabs", &state.tabs);
    // each screen: its opacity (and x for Effect::Slide) from the effect; 0.0 is its x in the design
    model.tabs_1 = ScreenView::new(state.tabs.screen(0, Effect::Fade, 1920.0), 0.0);
    model.slider = slot("#doc/slider", &state.slider);
    model.symbol = slot("#doc/symbol", &state.symbol);
    model.keyboard = slot("#doc/keyboard", &state.keyboard);
    model.bar_chart = slot("#doc/bar_chart", &state.bar_chart);
    model.input_field = slot("#doc/input_field", &state.input_field);
    model.tile = slot("#doc/tile", &state.tile);
    model.skeleton = slot("#doc/skeleton", &state.skeleton);
}

pub fn on_gesture(state: &mut State, node: &str, gesture: Gesture) {
    match node {
        "#doc/button" => {
            if let Some(ButtonEvent::Clicked) = state.button.on(gesture) {
                // yours
            }
        }
        "#doc/icon_button" => {
            if let Some(ButtonEvent::Clicked) = state.icon_button.on(gesture) {
                // yours
            }
        }
        "#doc/toggle" => {
            if let Some(ToggleEvent::Toggled(on)) = state.toggle.on(gesture) {
                let _ = on; // yours: state.toggle.value is the same
            }
        }
        _ if node.starts_with("#doc/radio/") => {
            // the option from its slot's name: #doc/radio/1 is index 0
            if let Some(i) = row_of("#doc/radio", node).and_then(|n| n.checked_sub(1)) {
                if let Some(RadioEvent::Selected(i)) = state.radio.on(i, gesture) {
                    let _ = i; // yours
                }
            }
        }
        "#doc/dropdown" => state.dropdown.on_field(gesture),
        // the open list's items report by their own names, #dropdown/item/1 ...
        _ if node.starts_with("#dropdown/item/") => {
            let n = node["#dropdown/item/".len()..].parse::<usize>().ok().and_then(|n| n.checked_sub(1));
            if let Some(DropdownEvent::Selected(i)) = n.and_then(|n| state.dropdown.on_item(n, gesture)) {
                let _ = i; // yours
            }
        }
        // the list itself (a drag between rows) or a row, "#doc/list_item/<row>"
        _ if node == "#doc/list_item" || node.starts_with("#doc/list_item/") => {
            if let Some(ListEvent::Chosen(row)) = state.list_item.on(row_of("#doc/list_item", node), gesture, Instant::now()) {
                let _ = row; // yours
            }
        }
        // the segments report by their own names, #segmented/segment-1 ...
        _ if node.starts_with("#segmented/segment-") => {
            let n = node["#segmented/segment-".len()..].parse::<usize>().ok().and_then(|n| n.checked_sub(1));
            if let Some(SegmentedEvent::Selected(i)) = n.and_then(|n| state.segmented.on(n, gesture)) {
                let _ = i; // yours: state.segmented.value() is the label
            }
        }
        // a tab reports with its tab bar: "#doc/tabs/#tabs/tab-2"
        _ if part_of("#doc/tabs", node).is_some() => {
            let tab = part_of("#doc/tabs", node).and_then(|p| p.strip_prefix("#tabs/tab-")).and_then(|n| n.parse::<usize>().ok());
            if let Some(TabsEvent::Selected(i)) = tab.and_then(|n| n.checked_sub(1)).and_then(|i| state.tabs.on(i, gesture)) {
                let _ = i; // yours: the presenter already shows screen i; send it on here if anyone else needs it
            }
        }
        "#doc/slider" => {
            if let Some(SliderEvent::Changed(value)) = state.slider.on(gesture) {
                let _ = value; // yours: the finger is up; Moving(value) while it drags
            }
        }
        // the keys report by their own names, #kbd/<row>/<i>
        _ if node.starts_with("#kbd/") => {
            let mut text = String::new(); // yours: the text of the field being edited
            if let Some(outcome) = state.keyboard.on(node, gesture, &mut text) {
                let _ = outcome;
            }
        }
        "#doc/input_field" => {
            if let Some(InputEvent::Focused) = state.input_field.on(gesture, Instant::now()) {
                // yours: open the keyboard (a Form does it for its fields)
            }
        }
        "#doc/tile" => {
            if let Some(TileEvent::Opened) = state.tile.on(gesture) {
                // yours: open the device's sheet
            }
        }
        // the control inside the card, by its part: state.tile.on_part(Some(part), gesture, tile_x, tile_y)
        // gives Toggled, Moving and Level, Mode or Step (in a list: row_of and part_of on the node)
        _ => {}
    }
}

#[test]
fn every_recipe_builds_a_model_and_takes_a_tap() {
    let mut state = State::new(&Sizes::none());
    let mut model = UiModel::new(HashMap::new());
    present(&mut model, &state);
    for node in ["#doc/button", "#doc/icon_button", "#doc/toggle", "#doc/radio/2", "#dropdown/item/1", "#doc/list_item/0", "#segmented/segment-2", "#doc/tabs/#tabs/tab-2", "#doc/slider", "#kbd/r1/1", "#doc/input_field", "#doc/tile"] {
        on_gesture(&mut state, node, Gesture::DOWN);
        on_gesture(&mut state, node, Gesture::UP);
    }
    present(&mut model, &state);
    // a tap on the toggle switched it, a tap on the second segment chose it
    assert!(state.toggle.value);
    assert_eq!(state.segmented.value(), "Med");
}
